def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\d+|[A-Z]+\d*|<>|<=|>=|[^\s]")
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def integer(text):
        # Small chunks also support literals beyond Python's digit limit.
        sign = 1
        if text[0] in "+-":
            if text[0] == "-":
                sign = -1
            text = text[1:]
        value = 0
        for start in range(0, len(text), 9):
            chunk = text[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return sign * value

    def parse(formula):
        values = []
        operators = []
        argument_counts = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                values.append(("neg", values.pop()))
                return

            right = values.pop()
            left = values.pop()
            if op == ":":
                values.append(("range", left[1], right[1]))
            else:
                values.append(("bin", op, left, right))

        for match in token_pattern.finditer(formula):
            token = match.group()

            if token[0].isdigit():
                values.append(("num", integer(token)))
                expect_operand = False

            elif token in functions:
                operators.append(token)
                expect_operand = True

            elif token[0].isalpha():
                values.append(("ref", token))
                expect_operand = False

            elif token == "(":
                operators.append("(")
                argument_counts.append(1)
                expect_operand = True

            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expect_operand = True

            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()

                if operators and operators[-1] in functions:
                    name = operators.pop()
                    args = tuple(values[-count:])
                    del values[-count:]
                    values.append(("call", name, args))

                expect_operand = False

            else:
                op = "neg" if token == "-" and expect_operand else token
                while operators and operators[-1] in precedence:
                    top = operators[-1]
                    if precedence[top] < precedence[op]:
                        break
                    if precedence[top] == precedence[op] and op == "neg":
                        break
                    reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()

        return values[0]

    def expand_arguments(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue

            first, last = arg[1], arg[2]
            col1, col2 = sorted((ord(first[0]), ord(last[0])))
            row1, row2 = sorted((int(first[1:]), int(last[1:])))

            for row in range(row1, row2 + 1):
                for col in range(col1, col2 + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("ref", name)

    memo = {}
    active = set()

    for root in cells:
        if root in memo:
            continue

        # Explicit stacks avoid recursion limits for formulas and cell chains.
        tasks = [("cell", root)]
        values = []

        while tasks:
            task = tasks.pop()
            action = task[0]

            if action == "cell":
                name = task[1]
                if name not in cells:
                    values.append(0)
                elif name in memo:
                    values.append(memo[name])
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    active.add(name)
                    tasks.append(("save", name))
                    content = cells[name]
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        values.append(integer(content))

            elif action == "save":
                name = task[1]
                memo[name] = values[-1]
                active.remove(name)

            elif action == "eval":
                node = task[1]
                kind = node[0]

                if kind == "num":
                    values.append(node[1])

                elif kind == "ref":
                    tasks.append(("cell", node[1]))

                elif kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("eval", node[1]))

                elif kind == "bin":
                    tasks.append(("left", node[1], node[3]))
                    tasks.append(("eval", node[2]))

                elif kind == "call":
                    name, args = node[1], node[2]
                    if name == "IF":
                        tasks.append(("choose", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        initial = 0 if name == "SUM" else None
                        tasks.append((
                            "fold", name, expand_arguments(args), initial
                        ))

            elif action == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif action == "left":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif action == "right":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                    continue

                op, left = task[1], task[2]
                if op == "+":
                    result = left + right
                elif op == "-":
                    result = left - right
                elif op == "*":
                    result = left * right
                elif op == "/":
                    if right == 0:
                        result = "#DIV/0!"
                    else:
                        result = abs(left) // abs(right)
                        if (left < 0) != (right < 0):
                            result = -result
                elif op == "=":
                    result = int(left == right)
                elif op == "<>":
                    result = int(left != right)
                elif op == "<":
                    result = int(left < right)
                elif op == "<=":
                    result = int(left <= right)
                elif op == ">":
                    result = int(left > right)
                else:
                    result = int(left >= right)

                values.append(result)

            elif action == "choose":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    branch = task[1] if condition else task[2]
                    tasks.append(("eval", branch))

            elif action == "fold":
                name, iterator, accumulator = task[1:]
                node = next(iterator, None)
                if node is None:
                    values.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append(("fold_value", name, iterator, accumulator))
                    tasks.append(("eval", node))

            elif action == "fold_value":
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                    continue

                name, iterator, accumulator = task[1:]
                if accumulator is None:
                    accumulator = value
                elif name == "SUM":
                    accumulator += value
                elif name == "MIN":
                    accumulator = min(accumulator, value)
                else:
                    accumulator = max(accumulator, value)

                tasks.append(("fold", name, iterator, accumulator))

    return {name: memo[name] for name in cells}
